// Bidirectional dictionary library, reimplementing the observable
// behavior of Python's `bidict` type used by the source program.
//
// - Copying a bidict produces an independent bidict (mutations to the
//   original do not affect the copy).
// - `inv` exposes the inverse view: looking up a value yields its key.
// - String representation matches Python's `repr(bidict(...))`.

import { pyReprValue } from './pyformat.mjs';

// Inverse view: maps values back to keys of the owning Bidict.
class InverseView {
  constructor(owner) {
    this._owner = owner;
  }

  get(value) {
    for (const [k, v] of this._owner._entries) {
      if (v === value) {
        return k;
      }
    }
    throw new Error(`KeyError: ${pyReprValue(value)}`);
  }
}

export class Bidict {
  constructor(entries = []) {
    // _entries preserves insertion order: array of [key, value] pairs.
    this._entries = [];
    for (const [k, v] of entries) {
      this.set(k, v);
    }
    this.inv = new InverseView(this);
  }

  set(key, value) {
    for (const pair of this._entries) {
      if (pair[0] === key) {
        pair[1] = value;
        return;
      }
    }
    this._entries.push([key, value]);
  }

  get(key) {
    for (const [k, v] of this._entries) {
      if (k === key) {
        return v;
      }
    }
    throw new Error(`KeyError: ${pyReprValue(key)}`);
  }

  // Independent shallow copy, like Python's bidict.copy().
  copy() {
    return new Bidict(this._entries.map(([k, v]) => [k, v]));
  }

  // Matches Python: bidict({'k1': v1, 'k2': v2})
  toString() {
    const parts = this._entries.map(
      ([k, v]) => `${pyReprValue(k)}: ${pyReprValue(v)}`
    );
    return `bidict({${parts.join(', ')}})`;
  }
}

export function bidict(entries) {
  if (entries === undefined) {
    return new Bidict();
  }
  // Accept a plain object (as in Python dict literal) or entry pairs.
  if (Array.isArray(entries)) {
    return new Bidict(entries);
  }
  return new Bidict(Object.entries(entries));
}

