// Helpers that reproduce Python's repr()/print() formatting for the
// value kinds used by this program (strings and integers).

export function pyReprValue(value) {
  if (typeof value === 'string') {
    return pyReprString(value);
  }
  if (typeof value === 'number') {
    return String(value);
  }
  return String(value);
}

// Python repr() of a str: single quotes by default, switching to double
// quotes only when the string contains a single quote but no double quote.
export function pyReprString(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else {
      out += ch;
    }
  }
  out += quote;
  return out;
}

