// Minimal re-implementation of the subset of Python's argparse behavior
// used by the source program: required options of type str / int given
// as `--name value` or `--name=value`.

export class ArgumentError extends Error {}

export function parseArgs(argv, spec, progName = 'test19.mjs') {
  const result = {};
  const seen = new Set();

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];
    if (!token.startsWith('--')) {
      fail(progName, `unrecognized arguments: ${token}`);
    }

    let name;
    let rawValue;
    const eq = token.indexOf('=');
    if (eq !== -1) {
      name = token.slice(2, eq);
      rawValue = token.slice(eq + 1);
    } else {
      name = token.slice(2);
      if (i + 1 >= argv.length) {
        fail(progName, `argument --${name}: expected one argument`);
      }
      rawValue = argv[i + 1];
      i += 1;
    }
    i += 1;

    const opt = spec[name];
    if (opt === undefined) {
      fail(progName, `unrecognized arguments: --${name}`);
    }

    if (opt.type === 'int') {
      const parsed = parsePythonInt(rawValue);
      if (parsed === null) {
        fail(
          progName,
          `argument --${name}: invalid int value: '${rawValue}'`
        );
      }
      result[name] = parsed;
    } else {
      result[name] = rawValue;
    }
    seen.add(name);
  }

  for (const [name, opt] of Object.entries(spec)) {
    if (opt.required && !seen.has(name)) {
      fail(progName, `the following arguments are required: --${name}`);
    }
  }

  return result;
}

// Python int(): optional sign, digits, surrounding whitespace allowed.
function parsePythonInt(s) {
  const trimmed = s.trim();
  if (!/^[+-]?\d+$/.test(trimmed)) {
    return null;
  }
  return parseInt(trimmed, 10);
}

function fail(progName, message) {
  process.stderr.write(`usage: ${progName} [-h]\n`);
  process.stderr.write(`${progName}: error: ${message}\n`);
  process.exit(2);
}

