// Entry point — Node.js (ESM) port of /workspace/dataset/bidict/test19.py.
// Run: node test19.mjs --k1 e --v1 23 --k2 s --v2 2

import { parseArgs } from './argparse.mjs';
import { bidict } from './bidict.mjs';

const args = parseArgs(
  process.argv.slice(2),
  {
    k1: { type: 'str', required: true },
    v1: { type: 'int', required: true },
    k2: { type: 'str', required: true },
    v2: { type: 'int', required: true },
  },
  'test19.mjs'
);

// 复制bidict
const b1 = bidict({ [args.k1]: args.v1, [args.k2]: args.v2 });
const b2 = b1.copy();
console.log(b2.toString());

// 修改原字典不影响副本
b1.set('new', 999);
console.log(b1.toString());
console.log(b2.toString());

// 副本的反转操作
const result = b2.inv.get(args.v1);
console.log(result);

